def compress(chars):
    result = []
    i = 0
    while i < len(chars):
        ch = chars[i]
        count = 0
        while i < len(chars) and chars[i] == ch:
            count += 1
            i += 1
        result.append(ch)
        if count > 1:
            result.extend(str(count))                            # each digit of the count as its own character
    for j in range(len(result)):
        chars[j] = result[j]                                        # copy the separate result back into chars
    del chars[len(result):]
    return len(result)


if __name__ == "__main__":
    chars = ["a", "a", "b", "b", "c", "c", "c"]
    new_length = compress(chars)
    print(new_length, chars[:new_length])

