import java.util.*;

public class Main {
    int compress(char[] chars) {
        List<Character> result = new ArrayList<>();
        int i = 0;
        while (i < chars.length) {
            char ch = chars[i];
            int count = 0;
            while (i < chars.length && chars[i] == ch) {
                count++;
                i++;
            }
            result.add(ch);
            if (count > 1) {
                for (char digit : String.valueOf(count).toCharArray()) result.add(digit); // each digit separately
            }
        }
        for (int j = 0; j < result.size(); j++) chars[j] = result.get(j);   // copy the separate result back into chars
        return result.size();
    }

    public static void main(String[] args) {
        char[] chars = {'a', 'a', 'b', 'b', 'c', 'c', 'c'};
        Main solution = new Main();
        int newLength = solution.compress(chars);
        System.out.println(newLength + " " + new String(chars, 0, newLength));
    }
}

