int compress(vector<char>& chars) {
    vector<char> result;
    int i = 0;
    while (i < (int)chars.size()) {
        char ch = chars[i];
        int count = 0;
        while (i < (int)chars.size() && chars[i] == ch) {
            count++;
            i++;
        }
        result.push_back(ch);
        if (count > 1) {
            for (char digit : to_string(count)) result.push_back(digit);  // each digit separately
        }
    }
    for (int j = 0; j < (int)result.size(); j++) chars[j] = result[j];      // copy the separate result back
    return (int)result.size();
}

